style.css:
@-moz-document domain("roblox.com") {
html {
    background: url("https://static.wikia.nocookie.net/bear-alt/images/6/6a/Monochromatic_New.png") no-repeat center center fixed !important;
    background-size: cover !important;
}

body {
    background: transparent !important;
}

/* Remove Roblox default backgrounds */
#container-main,
.container-main,
.content,
.page-content,
.content-wrapper,
.main-content,
.game-container,
.navbar,
.navbar-fixed-top {
    background-color: transparent !important;
}

/* Optional glass effect so text is readable */
.container-main,
.content,
.page-content {
    background: rgba(0,0,0,0.55) !important;
    backdrop-filter: blur(4px);
}
}
